insert into cryptocurrency_product(product_name, product_code, create_time, product_name_en, product_name_tc, product_name_de, product_name_es, product_name_fr, product_name_idn, product_name_jp, product_name_ko, product_name_my, product_name_th, product_name_vi, product_name_pt, product_name_rus, product_name_blr, product_name_ida, product_name_sa, product_name_ar, product_name_it)
select 'USDC', 'X:USDCUSD', NOW(), 'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC',	'USDC' from cryptocurrency_product where not exists (select product_code from cryptocurrency_product where product_code = 'X:USDCUSD')limit 1;
